def stepc(pieces, desc):
    """A step-function candidate for pick(): pieces are (a, b, y, left_closed, right_closed) horizontal segments from
    x = a to x = b at height y; each end gets a closed dot (included) or an open circle (excluded)."""
    fs = [(lambda x, a=a, b=b, y=y: y if a <= x <= b else None) for a, b, y, _, _ in pieces]
    holes, pts = [], []
    for a, b, y, lc, rc in pieces:
        for x_, closed in ((a, lc), (b, rc)):
            if closed:
                pts.append((x_, y, ''))
            else:
                holes.append((x_, y))
    return cand(fs, desc, holes=holes, pts=pts)


